-- Pearson Specter astronaut health monitoring demo
-- PostgreSQL 13+. IDs are generated by the database; timestamps are timestamptz.
BEGIN;

CREATE TABLE IF NOT EXISTS schema_migrations (
    version      INTEGER PRIMARY KEY,
    applied_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    description  TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS missions (
    id                        UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name                      TEXT NOT NULL,
    destination               TEXT NOT NULL DEFAULT 'ISS',
    earth_round_trip_seconds  INTEGER NOT NULL DEFAULT 0 CHECK (earth_round_trip_seconds >= 0),
    status                    TEXT NOT NULL DEFAULT 'active'
                                  CHECK (status IN ('planned', 'active', 'completed')),
    created_at                TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS astronauts (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    mission_id    UUID NOT NULL REFERENCES missions(id) ON DELETE RESTRICT,
    callsign      TEXT NOT NULL,
    display_name  TEXT NOT NULL,
    role          TEXT NOT NULL DEFAULT 'crew'
                      CHECK (role IN ('crew', 'medical_officer', 'commander')),
    active        BOOLEAN NOT NULL DEFAULT TRUE,
    joined_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (mission_id, callsign)
);

CREATE TABLE IF NOT EXISTS rule_sets (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    mission_id    UUID REFERENCES missions(id) ON DELETE RESTRICT,
    name          TEXT NOT NULL,
    version       TEXT NOT NULL,
    source_notes  TEXT,
    status        TEXT NOT NULL DEFAULT 'draft'
                      CHECK (status IN ('draft', 'active', 'retired')),
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_rule_sets_mission_name_version
    ON rule_sets(mission_id, name, version) WHERE mission_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_rule_sets_global_name_version
    ON rule_sets(name, version) WHERE mission_id IS NULL;

CREATE TABLE IF NOT EXISTS rules (
    id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    rule_set_id    UUID NOT NULL REFERENCES rule_sets(id) ON DELETE CASCADE,
    rule_key       TEXT NOT NULL,
    condition_key  TEXT NOT NULL,
    description    TEXT NOT NULL,
    criteria       JSONB NOT NULL DEFAULT '{}'::jsonb,
    response_tier  SMALLINT NOT NULL CHECK (response_tier BETWEEN 1 AND 3),
    enabled        BOOLEAN NOT NULL DEFAULT TRUE,
    UNIQUE (rule_set_id, rule_key)
);

CREATE TABLE IF NOT EXISTS vital_samples (
    id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    astronaut_id         UUID NOT NULL REFERENCES astronauts(id) ON DELETE RESTRICT,
    observed_at          TIMESTAMPTZ NOT NULL,
    received_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    source               TEXT NOT NULL DEFAULT 'simulator'
                             CHECK (source IN ('simulator', 'watch', 'manual', 'replay')),
    activity             TEXT CHECK (activity IN ('rest', 'walk', 'exercise', 'sleep', 'unknown')),
    heart_rate_bpm       DOUBLE PRECISION CHECK (heart_rate_bpm IS NULL OR heart_rate_bpm > 0),
    systolic_mmhg        DOUBLE PRECISION CHECK (systolic_mmhg IS NULL OR systolic_mmhg > 0),
    diastolic_mmhg       DOUBLE PRECISION CHECK (diastolic_mmhg IS NULL OR diastolic_mmhg > 0),
    spo2_percent         DOUBLE PRECISION CHECK (spo2_percent IS NULL OR spo2_percent BETWEEN 0 AND 100),
    temperature_c        DOUBLE PRECISION,
    breathing_rate_bpm   DOUBLE PRECISION CHECK (breathing_rate_bpm IS NULL OR breathing_rate_bpm > 0),
    radiation_rate       DOUBLE PRECISION CHECK (radiation_rate IS NULL OR radiation_rate >= 0),
    radiation_rate_unit  TEXT,
    skin_temperature_c   DOUBLE PRECISION,
    skin_conductance     DOUBLE PRECISION,
    motion_value         DOUBLE PRECISION,
    stress_value         DOUBLE PRECISION,
    sensor_status        TEXT NOT NULL DEFAULT 'ok'
                             CHECK (sensor_status IN ('ok', 'suspect', 'detached', 'fault')),
    scenario_key         TEXT,
    payload              JSONB NOT NULL DEFAULT '{}'::jsonb
);

CREATE INDEX IF NOT EXISTS idx_vital_samples_astronaut_time
    ON vital_samples(astronaut_id, observed_at DESC);
CREATE INDEX IF NOT EXISTS idx_vital_samples_scenario
    ON vital_samples(scenario_key, observed_at);

CREATE TABLE IF NOT EXISTS sleep_sessions (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    astronaut_id    UUID NOT NULL REFERENCES astronauts(id) ON DELETE RESTRICT,
    started_at      TIMESTAMPTZ NOT NULL,
    ended_at        TIMESTAMPTZ,
    source          TEXT NOT NULL CHECK (source IN ('watch', 'check_in', 'manual', 'simulator')),
    reported_hours  DOUBLE PRECISION CHECK (reported_hours IS NULL OR reported_hours >= 0),
    cycles_count    INTEGER CHECK (cycles_count IS NULL OR cycles_count >= 0),
    quality_score   DOUBLE PRECISION CHECK (quality_score IS NULL OR quality_score BETWEEN 0 AND 100),
    notes           TEXT,
    CHECK (ended_at IS NULL OR ended_at >= started_at)
);

CREATE INDEX IF NOT EXISTS idx_sleep_sessions_astronaut_start
    ON sleep_sessions(astronaut_id, started_at DESC);

CREATE TABLE IF NOT EXISTS sleep_stages (
    id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    sleep_session_id  UUID NOT NULL REFERENCES sleep_sessions(id) ON DELETE CASCADE,
    stage             TEXT NOT NULL CHECK (stage IN ('awake', 'light', 'deep', 'rem', 'unknown')),
    started_at        TIMESTAMPTZ NOT NULL,
    ended_at          TIMESTAMPTZ NOT NULL,
    CHECK (ended_at >= started_at)
);

CREATE INDEX IF NOT EXISTS idx_sleep_stages_session_start
    ON sleep_stages(sleep_session_id, started_at);

CREATE TABLE IF NOT EXISTS check_ins (
    id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    astronaut_id          UUID NOT NULL REFERENCES astronauts(id) ON DELETE RESTRICT,
    check_in_date         DATE NOT NULL,
    started_at            TIMESTAMPTZ NOT NULL,
    completed_at          TIMESTAMPTZ,
    status                TEXT NOT NULL DEFAULT 'in_progress'
                              CHECK (status IN ('in_progress', 'completed', 'missed', 'incomplete')),
    covers_previous_date  DATE,
    mood_score            DOUBLE PRECISION CHECK (mood_score IS NULL OR mood_score BETWEEN 0 AND 100),
    mental_health_score   DOUBLE PRECISION CHECK (mental_health_score IS NULL OR mental_health_score BETWEEN 0 AND 100),
    reported_symptoms     TEXT,
    agent_summary         TEXT,
    UNIQUE (astronaut_id, check_in_date)
);

CREATE INDEX IF NOT EXISTS idx_check_ins_astronaut_date
    ON check_ins(astronaut_id, check_in_date DESC);

CREATE TABLE IF NOT EXISTS check_in_answers (
    id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    check_in_id       UUID NOT NULL REFERENCES check_ins(id) ON DELETE CASCADE,
    question_key      TEXT NOT NULL,
    question_version  TEXT NOT NULL DEFAULT '1',
    answer_text       TEXT,
    answer_number     DOUBLE PRECISION,
    answered_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (check_in_id, question_key)
);

CREATE TABLE IF NOT EXISTS agent_conversations (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    astronaut_id  UUID NOT NULL REFERENCES astronauts(id) ON DELETE RESTRICT,
    started_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    ended_at      TIMESTAMPTZ,
    channel       TEXT NOT NULL DEFAULT 'dashboard'
                      CHECK (channel IN ('dashboard', 'watch', 'other')),
    status        TEXT NOT NULL DEFAULT 'open'
                      CHECK (status IN ('open', 'closed', 'handed_off')),
    CHECK (ended_at IS NULL OR ended_at >= started_at)
);

CREATE TABLE IF NOT EXISTS agent_messages (
    id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    conversation_id  UUID NOT NULL REFERENCES agent_conversations(id) ON DELETE CASCADE,
    sent_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    speaker          TEXT NOT NULL CHECK (speaker IN ('astronaut', 'manager_agent', 'watch_agent', 'mission_command')),
    message_text     TEXT NOT NULL,
    metadata          JSONB NOT NULL DEFAULT '{}'::jsonb
);

CREATE INDEX IF NOT EXISTS idx_agent_messages_conversation_time
    ON agent_messages(conversation_id, sent_at);

CREATE TABLE IF NOT EXISTS health_assessments (
    id                     UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    astronaut_id           UUID NOT NULL REFERENCES astronauts(id) ON DELETE RESTRICT,
    check_in_id            UUID REFERENCES check_ins(id) ON DELETE SET NULL,
    assessed_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    window_start           TIMESTAMPTZ NOT NULL,
    window_end             TIMESTAMPTZ NOT NULL,
    vitals_score           DOUBLE PRECISION CHECK (vitals_score IS NULL OR vitals_score BETWEEN 0 AND 100),
    root_cause_summary     TEXT,
    contributing_data      JSONB NOT NULL DEFAULT '{}'::jsonb,
    urgency                TEXT NOT NULL DEFAULT 'routine'
                               CHECK (urgency IN ('routine', 'urgent', 'emergency')),
    CHECK (window_end >= window_start)
);

CREATE INDEX IF NOT EXISTS idx_health_assessments_astronaut_time
    ON health_assessments(astronaut_id, assessed_at DESC);

CREATE TABLE IF NOT EXISTS condition_events (
    id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    astronaut_id      UUID NOT NULL REFERENCES astronauts(id) ON DELETE RESTRICT,
    started_at        TIMESTAMPTZ NOT NULL,
    ended_at          TIMESTAMPTZ,
    condition_key     TEXT NOT NULL,
    severity          TEXT NOT NULL CHECK (severity IN ('low', 'moderate', 'high', 'critical')),
    status            TEXT NOT NULL DEFAULT 'open'
                          CHECK (status IN ('open', 'monitoring', 'resolved', 'false_alarm')),
    reported_by       TEXT NOT NULL CHECK (reported_by IN ('watch', 'astronaut', 'crewmate', 'agent', 'simulator')),
    astronaut_report  TEXT,
    summary           TEXT,
    CHECK (ended_at IS NULL OR ended_at >= started_at)
);

CREATE INDEX IF NOT EXISTS idx_condition_events_astronaut_time
    ON condition_events(astronaut_id, started_at DESC);
CREATE INDEX IF NOT EXISTS idx_condition_events_status
    ON condition_events(status, severity, started_at DESC);

CREATE TABLE IF NOT EXISTS crew_alerts (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    condition_event_id  UUID NOT NULL REFERENCES condition_events(id) ON DELETE CASCADE,
    recipient_id        UUID NOT NULL REFERENCES astronauts(id) ON DELETE RESTRICT,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    acknowledged_at     TIMESTAMPTZ,
    alert_text          TEXT NOT NULL,
    action_instructions TEXT,
    status              TEXT NOT NULL DEFAULT 'pending'
                            CHECK (status IN ('pending', 'acknowledged', 'resolved', 'cancelled')),
    UNIQUE (condition_event_id, recipient_id)
);

CREATE INDEX IF NOT EXISTS idx_crew_alerts_recipient_status
    ON crew_alerts(recipient_id, status, created_at DESC);

CREATE TABLE IF NOT EXISTS decisions (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    astronaut_id        UUID NOT NULL REFERENCES astronauts(id) ON DELETE RESTRICT,
    condition_event_id  UUID REFERENCES condition_events(id) ON DELETE SET NULL,
    rule_id             UUID REFERENCES rules(id) ON DELETE SET NULL,
    decided_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    decision_type       TEXT NOT NULL,
    actor               TEXT NOT NULL CHECK (actor IN ('watch_llm', 'manager_agent', 'crew', 'mission_command', 'simulator')),
    rationale           TEXT NOT NULL,
    evidence            JSONB NOT NULL DEFAULT '{}'::jsonb,
    proposed_action     TEXT,
    outcome             TEXT CHECK (outcome IN ('proposed', 'accepted', 'rejected', 'cancelled', 'completed', 'superseded')),
    supersedes_id       UUID REFERENCES decisions(id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS idx_decisions_astronaut_time
    ON decisions(astronaut_id, decided_at DESC);
CREATE INDEX IF NOT EXISTS idx_decisions_condition
    ON decisions(condition_event_id, decided_at);

CREATE TABLE IF NOT EXISTS medications (
    id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name             TEXT NOT NULL UNIQUE,
    route            TEXT NOT NULL CHECK (route IN ('injection', 'iv', 'oral', 'other')),
    watch_injectable BOOLEAN NOT NULL DEFAULT FALSE,
    stock_unit       TEXT NOT NULL,
    active           BOOLEAN NOT NULL DEFAULT TRUE,
    notes            TEXT,
    CHECK (NOT watch_injectable OR route = 'injection')
);

CREATE TABLE IF NOT EXISTS medication_inventory (
    id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    mission_id       UUID NOT NULL REFERENCES missions(id) ON DELETE RESTRICT,
    medication_id    UUID NOT NULL REFERENCES medications(id) ON DELETE RESTRICT,
    lot_code         TEXT,
    quantity_on_hand NUMERIC(12, 3) NOT NULL CHECK (quantity_on_hand >= 0),
    expires_on       DATE,
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_medication_inventory_lot
    ON medication_inventory(mission_id, medication_id, lot_code) WHERE lot_code IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_medication_inventory_without_lot
    ON medication_inventory(mission_id, medication_id) WHERE lot_code IS NULL;

CREATE TABLE IF NOT EXISTS medication_events (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    astronaut_id        UUID NOT NULL REFERENCES astronauts(id) ON DELETE RESTRICT,
    mission_id          UUID NOT NULL REFERENCES missions(id) ON DELETE RESTRICT,
    medication_id       UUID NOT NULL REFERENCES medications(id) ON DELETE RESTRICT,
    condition_event_id  UUID REFERENCES condition_events(id) ON DELETE SET NULL,
    decision_id         UUID REFERENCES decisions(id) ON DELETE SET NULL,
    proposed_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    cancel_until        TIMESTAMPTZ,
    confirmed_at        TIMESTAMPTZ,
    administered_at     TIMESTAMPTZ,
    cancelled_at        TIMESTAMPTZ,
    status              TEXT NOT NULL DEFAULT 'proposed'
                            CHECK (status IN ('proposed', 'awaiting_confirmation', 'confirmed', 'cancelled', 'administered', 'crew_action_required', 'declined')),
    quantity            NUMERIC(12, 3) CHECK (quantity IS NULL OR quantity > 0),
    quantity_unit       TEXT,
    administered_by     TEXT,
    notes               TEXT,
    CHECK (cancel_until IS NULL OR cancel_until >= proposed_at),
    CHECK (administered_at IS NULL OR status = 'administered'),
    CHECK (cancelled_at IS NULL OR status = 'cancelled')
);

CREATE INDEX IF NOT EXISTS idx_medication_events_astronaut_time
    ON medication_events(astronaut_id, proposed_at DESC);
CREATE INDEX IF NOT EXISTS idx_medication_events_status
    ON medication_events(status, cancel_until);

CREATE TABLE IF NOT EXISTS treatment_plans (
    id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    astronaut_id         UUID NOT NULL REFERENCES astronauts(id) ON DELETE RESTRICT,
    health_assessment_id UUID REFERENCES health_assessments(id) ON DELETE SET NULL,
    created_by           TEXT NOT NULL CHECK (created_by IN ('manager_agent', 'medical_officer', 'mission_command')),
    created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    urgency              TEXT NOT NULL CHECK (urgency IN ('routine', 'urgent', 'emergency')),
    status               TEXT NOT NULL DEFAULT 'draft'
                             CHECK (status IN ('draft', 'awaiting_approval', 'approved', 'rejected', 'active', 'completed', 'cancelled')),
    rationale            TEXT NOT NULL,
    approved_by          TEXT,
    approved_at          TIMESTAMPTZ,
    earth_reply_due_at   TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS idx_treatment_plans_astronaut_time
    ON treatment_plans(astronaut_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_treatment_plans_status
    ON treatment_plans(status, urgency);

CREATE TABLE IF NOT EXISTS treatment_plan_items (
    id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    treatment_plan_id  UUID NOT NULL REFERENCES treatment_plans(id) ON DELETE CASCADE,
    position           INTEGER NOT NULL CHECK (position >= 0),
    action_type        TEXT NOT NULL CHECK (action_type IN ('medication', 'sleep', 'therapy', 'exercise', 'diet', 'monitoring', 'other')),
    description        TEXT NOT NULL,
    medication_id      UUID REFERENCES medications(id) ON DELETE RESTRICT,
    starts_at          TIMESTAMPTZ,
    ends_at            TIMESTAMPTZ,
    status             TEXT NOT NULL DEFAULT 'planned'
                           CHECK (status IN ('planned', 'in_progress', 'completed', 'skipped', 'cancelled')),
    UNIQUE (treatment_plan_id, position),
    CHECK (ends_at IS NULL OR starts_at IS NULL OR ends_at >= starts_at)
);

CREATE TABLE IF NOT EXISTS mission_reports (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    mission_id          UUID NOT NULL REFERENCES missions(id) ON DELETE RESTRICT,
    astronaut_id        UUID REFERENCES astronauts(id) ON DELETE SET NULL,
    report_type         TEXT NOT NULL CHECK (report_type IN ('weekly', 'emergency')),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    period_start        DATE,
    period_end          DATE,
    status              TEXT NOT NULL DEFAULT 'queued'
                            CHECK (status IN ('queued', 'sent', 'acknowledged', 'replied')),
    summary             TEXT NOT NULL,
    raw_data            JSONB NOT NULL DEFAULT '{}'::jsonb,
    flagged_issues      JSONB NOT NULL DEFAULT '[]'::jsonb,
    sent_at             TIMESTAMPTZ,
    CHECK (period_end IS NULL OR period_start IS NULL OR period_end >= period_start)
);

CREATE INDEX IF NOT EXISTS idx_mission_reports_queue
    ON mission_reports(mission_id, status, created_at);
CREATE UNIQUE INDEX IF NOT EXISTS idx_mission_reports_period
    ON mission_reports(mission_id, astronaut_id, report_type, period_start)
    WHERE report_type = 'weekly';

CREATE TABLE IF NOT EXISTS mission_command_replies (
    id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    report_id          UUID NOT NULL REFERENCES mission_reports(id) ON DELETE CASCADE,
    received_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    sender             TEXT NOT NULL,
    message            TEXT NOT NULL,
    instructions       JSONB NOT NULL DEFAULT '{}'::jsonb
);

CREATE TABLE IF NOT EXISTS lab_results (
    id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    astronaut_id   UUID NOT NULL REFERENCES astronauts(id) ON DELETE RESTRICT,
    collected_at   TIMESTAMPTZ NOT NULL,
    entered_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    panel_name     TEXT NOT NULL,
    analyte        TEXT NOT NULL,
    value          DOUBLE PRECISION NOT NULL,
    unit           TEXT NOT NULL,
    reference_low  DOUBLE PRECISION,
    reference_high DOUBLE PRECISION,
    source_notes   TEXT
);

CREATE INDEX IF NOT EXISTS idx_lab_results_astronaut_time
    ON lab_results(astronaut_id, collected_at DESC);

INSERT INTO schema_migrations(version, description)
VALUES (1, 'Initial PostgreSQL astronaut health monitoring schema')
ON CONFLICT (version) DO NOTHING;

COMMIT;
